const express = require('express');
const mysql = require('mysql2/promise');
const bodyParser = require('body-parser');
const dotenv = require('dotenv');
const cors = require('cors');
const bcrypt = require('bcryptjs');
const nodemailer = require('nodemailer');

// ==============================================
// 1. CONFIGURACIÓN INICIAL
// ==============================================
dotenv.config();
const app = express();

// ==============================================
// 2. HELPERS Y UTILIDADES
// ==============================================
const helpers = {
  formatDate: date => new Date(date).toISOString().split('T')[0],
  validateCoordinates: (lat, lng) => !isNaN(lat) && !isNaN(lng) && lat >= -90 && lat <= 90 && lng >= -180 && lng <= 180,
  validateUserId: (req, res, next) => {
    if (!req.params.userId) {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'ID de usuario es requerido'
      });
    }
    next();
  }
};

// ==============================================
// 3. MIDDLEWARE GENERAL
// ==============================================
app.use(cors({
  origin: process.env.FRONTEND_URL || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({
  extended: true
}));

// ==============================================
// 4. CONFIGURACIÓN DE BASE DE DATOS
// ==============================================
const db = mysql.createPool({
  connectionLimit: 20,
  host: process.env.DB_HOST,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,
  port: process.env.DB_PORT,
  waitForConnections: true,
  connectTimeout: 10000,
  idleTimeout: 60000,
  queueLimit: 0,
  enableKeepAlive: true,
  keepAliveInitialDelay: 0
});
db.on('error', err => {
  console.error('💥 Error en el pool de MySQL:', err.code);
});

// Middleware de conexión a DB
app.use(async (req, res, next) => {
  try {
    const connection = await db.getConnection();
    req.dbConnection = connection;
    res.on('finish', () => connection.release());
    next();
  } catch (err) {
    console.error('❌ Error de conexión:', err.message);
    res.status(503).json({
      error: 'Service Unavailable',
      message: 'Error al conectar con la BD'
    });
  }
});

// ==============================================
// 5. FUNCIONES AUXILIARES
// ==============================================
async function sendEmail(to, subject, text) {
  try {
    const transporter = nodemailer.createTransport({
      service: process.env.EMAIL_SERVICE || 'gmail',
      auth: {
        user: process.env.EMAIL_USER,
        pass: process.env.EMAIL_PASS
      }
    });
    await transporter.sendMail({
      from: `"Sistema Requena" <${process.env.EMAIL_USER}>`,
      to,
      subject,
      text,
      html: `<div style="font-family: Arial, sans-serif;">
               <h2 style="color: #d32f2f;">Requena Abogados</h2>
               <p>${text.replace(/\n/g, '<br>')}</p>
               <hr>
               <small>Mensaje automático</small>
             </div>`
    });
    console.log(`📧 Email enviado a ${to}`);
  } catch (err) {
    console.error('Error al enviar email:', err.message);
    throw err;
  }
}

