app.post('/users/:userId/vacation-request', helpers.validateUserId, async (req, res) => {
  const {
    userId
  } = req.params;
  const {
    dates
  } = req.body;
  const connection = req.dbConnection;
  if (!dates || !Array.isArray(dates) || dates.length === 0) {
    return res.status(400).json({
      error: 'Validation Error',
      message: 'Debes seleccionar al menos un día'
    });
  }
  const today = helpers.formatDate(new Date());
  const formattedDates = dates.map(helpers.formatDate);
  try {
    // Validar fechas
    const invalidDates = formattedDates.filter(d => d < today);
    if (invalidDates.length > 0) {
      return res.status(400).json({
        error: 'Validation Error',
        message: `No puedes solicitar fechas pasadas: ${invalidDates.join(', ')}`
      });
    }

    // Validar duplicados
    const [existing] = await connection.query(`SELECT vacation_date FROM vacation_requests
         WHERE user_id = ? AND vacation_date IN (?)`, [userId, formattedDates]);
    if (existing.length > 0) {
      return res.status(400).json({
        error: 'Validation Error',
        message: `Ya tienes solicitudes para: ${existing.map(r => r.vacation_date).join(', ')}`
      });
    }
    await connection.beginTransaction();

    // Obtener usuario
    const [[user]] = await connection.query(`SELECT name, email, vacation_days FROM users WHERE id = ? FOR UPDATE`, [userId]);
    if (!user) {
      await connection.rollback();
      return res.status(404).json({
        error: 'Usuario no encontrado'
      });
    }

    // Validar días disponibles
    if (dates.length > user.vacation_days) {
      await connection.rollback();
      return res.status(400).json({
        error: 'Validation Error',
        message: `Días insuficientes. Disponibles: ${user.vacation_days}, Solicitados: ${dates.length}`
      });
    }

    // Insertar solicitudes
    const values = dates.map(date => [userId, helpers.formatDate(date), helpers.formatDate(date), 'pending', null, helpers.formatDate(date)]);
    await connection.query(`INSERT INTO vacation_requests
           (user_id, start_date, end_date, status, comments, vacation_date)
         VALUES ?`, [values]);

    // Actualizar días
    const newVacationDays = user.vacation_days - dates.length;

    // Notificar admins
    const [admins] = await connection.query(`SELECT email FROM users WHERE role = 'admin'`);
    const message = `Nueva solicitud de ${user.name} para:\n${dates.map(d => '- ' + helpers.formatDate(d)).join('\n')}`;
    await Promise.all(admins.map(admin => sendEmail(admin.email, 'Nueva solicitud de vacaciones', message)));
    await connection.commit();
    res.status(201).json({
      message: 'Solicitud registrada',
      remaining_days: user.vacation_days
    });
  } catch (err) {
    await connection.rollback();
    console.error('Error al solicitar vacaciones:', err.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al procesar la solicitud'
    });
  }
});

