app.put('/admin/vacation-requests/:requestId', async (req, res) => {
  const {
    requestId
  } = req.params;
  const {
    status,
    comments
  } = req.body;
  const connection = req.dbConnection;
  if (!status || !['approved', 'rejected'].includes(status)) {
    return res.status(400).json({
      error: 'Validation Error',
      message: 'Estado debe ser "approved" o "rejected"'
    });
  }
  try {
    await connection.beginTransaction();

    // 1. Actualizar estado
    const [result] = await connection.query(`UPDATE vacation_requests
         SET status = ?, comments = ?
         WHERE id = ?`, [status, comments || null, requestId]);
    if (result.affectedRows === 0) {
      await connection.rollback();
      return res.status(404).json({
        error: 'Not Found',
        message: 'Solicitud no encontrada'
      });
    }

    // 2. Obtener info para notificación
    const [[request]] = await connection.query(`SELECT u.email, u.name, DATE_FORMAT(vr.vacation_date, '%Y-%m-%d')
         FROM vacation_requests vr
                JOIN users u ON vr.user_id = u.id
         WHERE vr.id = ?`, [requestId]);

    // 3. Enviar notificación
    const emailText = `Tu solicitud para ${request.vacation_date} ha sido ${status}.\n\n${comments ? `Comentarios: ${comments}\n\n` : ''}Saludos,\nEquipo de Requena Abogados`;
    await sendEmail(request.email, `Solicitud ${status}`, emailText);
    await connection.commit();
    res.status(200).json({
      message: `Solicitud ${status} correctamente`
    });
  } catch (err) {
    await connection.rollback();
    console.error('Error al procesar solicitud:', err.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al procesar solicitud'
