const express = require('express');
const mysql = require('mysql2/promise');
const bodyParser = require('body-parser');
const dotenv = require('dotenv');
const cors = require('cors');
const bcrypt = require('bcryptjs');
const nodemailer = require('nodemailer');

// ==============================================
// 1. CONFIGURACIÓN INICIAL
// ==============================================
dotenv.config();
const app = express();

// ==============================================
// 2. HELPERS Y UTILIDADES
// ==============================================
const helpers = {
  formatDate: (date) => new Date(date).toISOString().split('T')[0],
  validateCoordinates: (lat, lng) =>
      !isNaN(lat) && !isNaN(lng) &&
      lat >= -90 && lat <= 90 &&
      lng >= -180 && lng <= 180,
  validateUserId: (req, res, next) => {
    if (!req.params.userId) {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'ID de usuario es requerido'
      });
    }
    next();
  }
};

// ==============================================
// 3. MIDDLEWARE GENERAL
// ==============================================
app.use(cors({
  origin: process.env.FRONTEND_URL || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));

// ==============================================
// 4. CONFIGURACIÓN DE BASE DE DATOS
// ==============================================
const db = mysql.createPool({
  connectionLimit: 20,
  host: process.env.DB_HOST,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,
  port: process.env.DB_PORT,
  waitForConnections: true,
  connectTimeout: 10000,
  idleTimeout: 60000,
  queueLimit: 0,
  enableKeepAlive: true,
  keepAliveInitialDelay: 0
});

db.on('error', (err) => {
  console.error('💥 Error en el pool de MySQL:', err.code);
});

// Middleware de conexión a DB
app.use(async (req, res, next) => {
  try {
    const connection = await db.getConnection();
    req.dbConnection = connection;
    res.on('finish', () => connection.release());
    next();
  } catch (err) {
    console.error('❌ Error de conexión:', err.message);
    res.status(503).json({
      error: 'Service Unavailable',
      message: 'Error al conectar con la BD'
    });
  }
});

// ==============================================
// 5. FUNCIONES AUXILIARES
// ==============================================
async function sendEmail(to, subject, text) {
  try {
    const transporter = nodemailer.createTransport({
      service: process.env.EMAIL_SERVICE || 'gmail',
      auth: {
        user: process.env.EMAIL_USER,
        pass: process.env.EMAIL_PASS
      }
    });

    await transporter.sendMail({
      from: `"Sistema Requena" <${process.env.EMAIL_USER}>`,
      to,
      subject,
      text,
      html: `<div style="font-family: Arial, sans-serif;">
               <h2 style="color: #d32f2f;">Requena Abogados</h2>
               <p>${text.replace(/\n/g, '<br>')}</p>
               <hr>
               <small>Mensaje automático</small>
             </div>`
    });
    console.log(`📧 Email enviado a ${to}`);
  } catch (err) {
    console.error('Error al enviar email:', err.message);
    throw err;
  }
}

// ==============================================
// 6. ENDPOINTS DE USUARIO
// ==============================================

// Health Check
app.get('/health', async (req, res) => {
  try {
    const [rows] = await db.query('SELECT 1');
    res.json({
      status: 'healthy',
      db: 'connected',
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    res.status(503).json({
      status: 'unhealthy',
      db: 'disconnected',
      error: err.message
    });
  }
});

// Login
app.post('/users/login', async (req, res) => {
  const { email, password } = req.body;
  const connection = req.dbConnection;

  if (!email || !password) {
    return res.status(400).json({
      error: 'Validation Error',
      message: 'Correo y contraseña son requeridos'
    });
  }

  try {
    const [results] = await connection.query(
        'SELECT * FROM users WHERE email = ?',
        [email]
    );

    if (results.length === 0) {
      return res.status(404).json({
        error: 'Not Found',
        message: 'Usuario no encontrado'
      });
    }

    const user = results[0];
    const isPasswordValid = await bcrypt.compare(password, user.password);

    if (!isPasswordValid) {
      return res.status(401).json({
        error: 'Unauthorized',
        message: 'Contraseña incorrecta'
      });
    }

    res.status(200).json({
      message: 'Inicio de sesión exitoso',
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        role: user.role,
        vacation_days: user.vacation_days,
      },
    });
  } catch (err) {
    console.error('Error en login:', err.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al procesar la solicitud'
    });
  }
});

// Obtener días de vacaciones
app.get('/users/:userId/vacation-days', helpers.validateUserId, async (req, res) => {
  const { userId } = req.params;
  const connection = req.dbConnection;

  try {
    const [results] = await connection.query(
        'SELECT vacation_days FROM users WHERE id = ?',
        [userId]
    );

    if (results.length === 0) {
      return res.status(404).json({
        error: 'Not Found',
        message: 'Usuario no encontrado'
      });
    }

    res.status(200).json({
      vacation_days: results[0].vacation_days
    });
  } catch (err) {
    console.error('Error al obtener días de vacaciones:', err.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al obtener días de vacaciones'
    });
  }
});

// Registrar check-in
app.post('/users/checkIn', async (req, res) => {
  const { userId, latitude, longitude } = req.body;
  const connection = req.dbConnection;

  if (!userId || !helpers.validateCoordinates(latitude, longitude)) {
    return res.status(400).json({
      error: 'Validation Error',
      message: 'Datos inválidos'
    });
  }

  try {
    await connection.query(
        `INSERT INTO checkins (user_id, latitude, longitude, type, timestamp)
         VALUES (?, ?, ?, 'checkin', NOW())`,
        [userId, latitude, longitude]
    );
    res.status(200).json({
      message: 'Check-in registrado',
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    console.error('Error al registrar check-in:', err.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al registrar check-in'
    });
  }
});

// Registrar check-out
app.post('/users/checkOut', async (req, res) => {
  const { userId, latitude, longitude } = req.body;
  const connection = req.dbConnection;

  if (!userId || !helpers.validateCoordinates(latitude, longitude)) {
    return res.status(400).json({
      error: 'Validation Error',
      message: 'Datos inválidos'
    });
  }

  try {
    await connection.query(
        `INSERT INTO checkins (user_id, latitude, longitude, type, timestamp)
         VALUES (?, ?, ?, 'checkout', NOW())`,
        [userId, latitude, longitude]
    );
    res.status(200).json({
      message: 'Check-out registrado',
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    console.error('Error al registrar check-out:', err.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al registrar check-out'
    });
  }
});

// Verificar estado de check-in
app.get('/users/:userId/checkIn-status', helpers.validateUserId, async (req, res) => {
  const { userId } = req.params;
  const connection = req.dbConnection;

  try {
    const [results] = await connection.query(
        `SELECT * FROM checkins
         WHERE user_id = ?
           AND DATE(timestamp) = CURDATE()
           AND type = 'checkin'`,
        [userId]
    );

    res.status(200).json({ checkedIn: results.length > 0 });
  } catch (err) {
    console.error('Error al verificar check-in:', err.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al verificar estado de check-in'
    });
  }
});

// Verificar estado de check-out
app.get('/users/:userId/checkOut-status', helpers.validateUserId, async (req, res) => {
  const { userId } = req.params;
  const connection = req.dbConnection;

  try {
    const [results] = await connection.query(
        `SELECT * FROM checkins
         WHERE user_id = ?
           AND DATE(timestamp) = CURDATE()
           AND type = 'checkout'`,
        [userId]
    );

    res.status(200).json({ alreadyCheckedOut: results.length > 0 });
  } catch (err) {
    console.error('Error al verificar check-out:', err.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al verificar estado de check-out'
    });
  }
});

// Solicitar vacaciones
app.post('/users/:userId/vacation-request', helpers.validateUserId, async (req, res) => {
  const { userId } = req.params;
  const { dates } = req.body;
  const connection = req.dbConnection;

  if (!dates || !Array.isArray(dates) || dates.length === 0) {
    return res.status(400).json({
      error: 'Validation Error',
      message: 'Debes seleccionar al menos un día'
    });
  }

  const today = helpers.formatDate(new Date());
  const formattedDates = dates.map(helpers.formatDate);

  try {
    // Validar fechas
    const invalidDates = formattedDates.filter(d => d < today);
    if (invalidDates.length > 0) {
      return res.status(400).json({
        error: 'Validation Error',
        message: `No puedes solicitar fechas pasadas: ${invalidDates.join(', ')}`
      });
    }

    // Validar duplicados
    const [existing] = await connection.query(
        `SELECT vacation_date FROM vacation_requests
         WHERE user_id = ? AND vacation_date IN (?)`,
        [userId, formattedDates]
    );

    if (existing.length > 0) {
      return res.status(400).json({
        error: 'Validation Error',
        message: `Ya tienes solicitudes para: ${existing.map(r => r.vacation_date).join(', ')}`
      });
    }

    await connection.beginTransaction();

    // Obtener usuario
    const [[user]] = await connection.query(
        `SELECT name, email, vacation_days FROM users WHERE id = ? FOR UPDATE`,
        [userId]
    );

    if (!user) {
      await connection.rollback();
      return res.status(404).json({ error: 'Usuario no encontrado' });
    }

    // Validar días disponibles
    if (dates.length > user.vacation_days) {
      await connection.rollback();
      return res.status(400).json({
        error: 'Validation Error',
        message: `Días insuficientes. Disponibles: ${user.vacation_days}, Solicitados: ${dates.length}`
      });
    }

    // Insertar solicitudes
    const values = dates.map(date => [
      userId,
      helpers.formatDate(date),
      helpers.formatDate(date),
      'pending',
      null,
      helpers.formatDate(date)
    ]);

    await connection.query(
        `INSERT INTO vacation_requests
           (user_id, start_date, end_date, status, comments, vacation_date)
         VALUES ?`,
        [values]
    );

    // Actualizar días
    const newVacationDays = user.vacation_days - dates.length;


    // Notificar admins
    const [admins] = await connection.query(
        `SELECT email FROM users WHERE role = 'admin'`
    );

    const message = `Nueva solicitud de ${user.name} para:\n${dates.map(d => '- ' + helpers.formatDate(d)).join('\n')}`;

    await Promise.all(admins.map(admin =>
        sendEmail(admin.email, 'Nueva solicitud de vacaciones', message)
    ));

    await connection.commit();

    res.status(201).json({
      message: 'Solicitud registrada',
      remaining_days: user.vacation_days
    });
  } catch (err) {
    await connection.rollback();
    console.error('Error al solicitar vacaciones:', err.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al procesar la solicitud'
    });
  }
});

// Obtener historial de vacaciones
app.get('/users/:userId/vacation-history', helpers.validateUserId, async (req, res) => {
  const { userId } = req.params;
