// ==============================================
// 7. ENDPOINTS DE ADMINISTRACIÓN
// ==============================================
// Obtener solicitudes agrupadas para administradores (NUEVO)
app.get('/admin/grouped-vacation-requests', async (req, res) => {
  const connection = req.dbConnection;

  try {
    const [results] = await connection.query(`
      SELECT 
        vr.request_group_id as groupId,
        u.id as userId,
        u.name as userName,
        u.email as userEmail,
        MIN(DATE_FORMAT(vr.vacation_date, '%Y-%m-%d')) as startDate,
        MAX(DATE_FORMAT(vr.vacation_date, '%Y-%m-%d')) as endDate,
        COUNT(*) as totalDays,
        vr.status,
        vr.comments,
        GROUP_CONCAT(DATE_FORMAT(vr.vacation_date, '%Y-%m-%d') ORDER BY DATE_FORMAT(vr.vacation_date, '%Y-%m-%d') SEPARATOR ', ') as datesList,
        MAX(vr.notification_read) as notificationRead
      FROM vacation_requests vr
      JOIN users u ON vr.user_id = u.id
      GROUP BY vr.request_group_id, u.id, u.name, u.email, vr.status, vr.comments
      ORDER BY status ASC, startDate DESC
    `);

    // Formatear resultados para el frontend
    const formattedResults = results.map(group => ({
      ...group,
      notificationRead: Boolean(group.notificationRead),
      dates: group.datesList.split(', ').sort()
    }));

    res.status(200).json(formattedResults);
  } catch (error) {
    console.error('Error al obtener solicitudes agrupadas:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al obtener solicitudes de vacaciones'
    });
  }
});
// Obtener todos los usuarios
app.get('/admin/users', async (req, res) => {
  const connection = req.dbConnection;

  try {
    const [results] = await connection.query(
        `SELECT id, name, email, role, vacation_days
         FROM users`
    );
    res.status(200).json(results);
  } catch (err) {
