    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al obtener usuarios'
    });
  }
});

// Obtener checkins de usuario
app.get('/admin/user-checkins/:userId', helpers.validateUserId, async (req, res) => {
  const { userId } = req.params;
  const connection = req.dbConnection;

  try {
    const [results] = await connection.query(
        `SELECT id, user_id, latitude, longitude,
                DATE_FORMAT(timestamp, '%Y-%m-%d %H:%i:%s') as timestamp,
              type
         FROM checkins
         WHERE user_id = ?
         ORDER BY timestamp DESC`,
        [userId]
    );
    res.status(200).json(results);
  } catch (err) {
    console.error('Error al obtener check-ins:', err.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al obtener historial'
    });
  }
});

// Eliminar usuario
app.delete('/admin/delete-user/:userId', helpers.validateUserId, async (req, res) => {
  const { userId } = req.params;
  const connection = req.dbConnection;

  try {
    // Verificar si el usuario tiene check-ins
    const [[{ total_checkins }]] = await connection.query(
        `SELECT COUNT(*) AS total_checkins FROM checkins WHERE user_id = ?`,
        [userId]
    );

    if (total_checkins > 0) {
      return res.status(400).json({
        error: 'Protected Data',
        message: 'No se puede eliminar usuario con historial de check-ins'
      });
    }

    // Eliminar usuario
    const [result] = await connection.query(
        `DELETE FROM users WHERE id = ?`,
        [userId]
    );

    if (result.affectedRows === 0) {
      return res.status(404).json({
        error: 'Not Found',
        message: 'Usuario no encontrado'
      });
    }

    res.status(200).json({
      message: 'Usuario eliminado correctamente'
    });
  } catch (err) {
    console.error('Error al eliminar usuario:', err.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al eliminar usuario'
    });
  }
});

// Actualizar usuario
app.put('/admin/update-user/:userId', helpers.validateUserId, async (req, res) => {
  const { userId } = req.params;
  const { name, email, vacation_days, role } = req.body;
  const connection = req.dbConnection;

  // Validaciones
