const crypto = require('crypto');

// Solicitar vacaciones con agrupación (versión mejorada)
app.post('/users/:userId/vacation-request-grouped', helpers.validateUserId, async (req, res) => {
  const { userId } = req.params;
  const { dates } = req.body;
  const connection = req.dbConnection;

  // Validación básica
  if (!dates || !Array.isArray(dates) || dates.length === 0) {
    return res.status(400).json({
      error: 'Validation Error',
      message: 'Debes seleccionar al menos un día'
    });
  }

  // Formatear y ordenar fechas
  const formattedDates = dates.map(date => {
    try {
      return helpers.formatDate(new Date(date));
    } catch (e) {
      return null;
    }
  }).filter(date => date !== null).sort();

  const today = helpers.formatDate(new Date());

  try {
    // Validación de fechas
    const invalidDates = formattedDates.filter(d => d < today);
    if (invalidDates.length > 0) {
      return res.status(400).json({
        error: 'Validation Error',
        message: `No puedes solicitar fechas pasadas: ${invalidDates.join(', ')}`
      });
    }

    // Verificar duplicados
    const [existing] = await connection.query(
        `SELECT vacation_date FROM vacation_requests
       WHERE user_id = ? AND vacation_date IN (?)`,
        [userId, formattedDates]
    );

    if (existing.length > 0) {
      return res.status(400).json({
        error: 'Validation Error',
        message: `Ya tienes solicitudes para: ${existing.map(r => r.vacation_date).join(', ')}`
      });
    }

    await connection.beginTransaction();

    // Obtener información del usuario con bloqueo
    const [[user]] = await connection.query(
        `SELECT name, email, vacation_days FROM users WHERE id = ? FOR UPDATE`,
        [userId]
    );

    if (!user) {
      await connection.rollback();
      return res.status(404).json({ error: 'Usuario no encontrado' });
    }

    // Validar días disponibles
    if (formattedDates.length > user.vacation_days) {
      await connection.rollback();
      return res.status(400).json({
        error: 'Validation Error',
        message: `Días insuficientes. Disponibles: ${user.vacation_days}, Solicitados: ${formattedDates.length}`
      });
    }

    // Crear grupo de solicitudes
    const requestGroupId = crypto.randomUUID();
    const values = formattedDates.map(date => [
      userId,
      date, // start_date
      date, // end_date
      'pending', // status
      null, // comments
      date, // vacation_date
      0, // notification_read (0 = false)
      requestGroupId // request_group_id
    ]);

    // Insertar todas las fechas
    await connection.query(
        `INSERT INTO vacation_requests
        (user_id, start_date, end_date, status, comments, vacation_date, notification_read, request_group_id)
       VALUES ?`,
        [values]
    );

    // Actualizar días de vacaciones (reservarlos)
    await connection.query(
        `UPDATE users SET vacation_days = vacation_days - ? WHERE id = ?`,
        [formattedDates.length, userId]
    );

    // Notificar a administradores
    const [admins] = await connection.query(
        `SELECT email FROM users WHERE role = 'admin'`
    );

    const emailText = `Nueva solicitud de ${user.name} (${formattedDates.length} días):
Del ${formattedDates[0]} al ${formattedDates[formattedDates.length - 1]}

Fechas solicitadas:
${formattedDates.map(d => `- ${d}`).join('\n')}

Días restantes: ${user.vacation_days - formattedDates.length}`;

    await Promise.all(admins.map(admin =>
        sendEmail(admin.email, 'Nueva solicitud de vacaciones', emailText)
    ));

    await connection.commit();

    res.status(201).json({
      success: true,
      message: 'Solicitud registrada correctamente',
      requestGroupId,
      daysRequested: formattedDates.length,
      remainingDays: user.vacation_days - formattedDates.length
    });

  } catch (error) {
    await connection.rollback();
    console.error('Error en solicitud agrupada:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al procesar la solicitud'
    });
  }
});

