app.put('/admin/vacation-request-group/:groupId', async (req, res) => {
  const { groupId } = req.params;
  const { status, comments } = req.body;
  const connection = req.dbConnection;

  if (!status || !['approved', 'rejected'].includes(status)) {
    return res.status(400).json({
      error: 'Validation Error',
      message: 'Estado debe ser "approved" o "rejected"'
    });
  }

  try {
    await connection.beginTransaction();

    const [rows] = await connection.query(
        `SELECT vr.*, u.email, u.name, u.vacation_days
         FROM vacation_requests vr
         JOIN users u ON vr.user_id = u.id
         WHERE vr.request_group_id = ?`,
        [groupId]
    );

    if (rows.length === 0) {
      await connection.rollback();
      return res.status(404).json({ error: 'Solicitud no encontrada' });
    }

    const user = rows[0];
    const fechas = rows.map(r => r.vacation_date);

    await connection.query(
        `UPDATE vacation_requests
         SET status = ?, comments = ?
         WHERE request_group_id = ?`,
        [status, comments || null, groupId]
    );

    if (status === 'approved') {
      const newTotal = user.vacation_days - fechas.length;
      await connection.query(
          `UPDATE users SET vacation_days = ? WHERE id = ?`,
          [newTotal, user.user_id]
      );
    }

    const msg = `Tu solicitud del \${fechas[0]} al \${fechas[fechas.length - 1]} ha sido \${status}.
` +
        (comments ? `Comentarios: \${comments}
` : '') +
        '\nSaludos,\nEquipo de Requena Abogados';

    await sendEmail(user.email, `Solicitud \${status}`, msg);

    await connection.commit();
    res.status(200).json({
      message: `Solicitud \${status} correctamente`
    });
  } catch (err) {
    await connection.rollback();
    console.error('Error al actualizar solicitud por grupo:', err.message);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Error al actualizar solicitud por grupo'
    });
  }
});

